<script setup lang="ts">import GModal from '../GModal/GModal.vue'; import type { TextContent } from '@/shared/types/components'; import { useLocalizedText } from '@/shared/composables/localization/useLocalizedText'; const props = withDefaults(defineProps<{ open?: boolean; title?: TextContent; label?: TextContent }>(), { open: false, label: () => ({ table: 'Common', textKey: '#DRAWER' }) }); const labelText = useLocalizedText(() => props.label); const emit = defineEmits<{ 'update:open': [value: boolean] }>()</script>
<template><GModal :open="open" :title="title" @update:open="emit('update:open', $event)"><aside class="ew-drawer" :aria-label="labelText"><slot /></aside></GModal></template>
